package com.archos.mediacenter.video.leanback;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import com.archos.mediacenter.video.leanback.PreviewLibraryLoader.*;
import java.util.*;
import org.json.*;

/** Home presentation and explicit row membership. Never changes playback or watched state. */
public final class PreviewHomeRows {
 public static final String[] SYSTEM={"continue","watchnext","recent","trending","popular","watched","similar"};
 private static final String[] LABELS={"Continue Watching","Watch Next","Recently Added","Trending on Trakt — In Your Library","Popular on Trakt — In Your Library","Recently Watched","Because You Watched"};
 public static final class Row {public String id,name;public boolean visible=true,dynamic=false,movies=true,tv=true;public String genreRule="",sort="added";public int maximum=0;public final Set<String> members=new LinkedHashSet<>();Row(String id,String name){this.id=id;this.name=name;}public boolean custom(){return id.startsWith("custom:");}}
 private final Context context;private final SharedPreferences prefs;public final List<Row> rows=new ArrayList<>();
 public PreviewHomeRows(Context c){context=c;prefs=androidx.preference.PreferenceManager.getDefaultSharedPreferences(c);try{JSONArray data=new JSONArray(prefs.getString("preview_home_rows41","[]"));for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);Row r=new Row(o.getString("id"),o.getString("name"));r.visible=o.optBoolean("visible",true);r.dynamic=o.optBoolean("dynamic",false);r.movies=o.optBoolean("movies",true);r.tv=o.optBoolean("tv",true);if(!r.movies&&!r.tv)r.movies=true;r.genreRule=o.optString("genres","");r.sort=o.optString("sort","added");r.maximum=Math.max(0,o.optInt("maximum",0));JSONArray members=o.optJSONArray("members");if(members!=null)for(int j=0;j<members.length();j++)r.members.add(members.getString(j));rows.add(r);}}catch(JSONException ignored){}for(int i=0;i<SYSTEM.length;i++){final String id=SYSTEM[i];if(rows.stream().noneMatch(r->r.id.equals(id)))rows.add(new Row(id,LABELS[i]));}}
 private void save(){JSONArray data=new JSONArray();try{for(Row r:rows)data.put(new JSONObject().put("id",r.id).put("name",r.name).put("visible",r.visible).put("members",new JSONArray(r.members)).put("dynamic",r.dynamic).put("movies",r.movies).put("tv",r.tv).put("genres",r.genreRule).put("sort",r.sort).put("maximum",r.maximum));prefs.edit().putString("preview_home_rows41",data.toString()).apply();}catch(JSONException error){throw new IllegalStateException(error);}}
 public List<Entry> members(Row row,Snapshot snapshot){List<Entry> result=new ArrayList<>();if(row.dynamic){List<Entry> source=new ArrayList<>();if(row.movies)source.addAll(snapshot.movies);if(row.tv)source.addAll(snapshot.shows);Set<String> genres=PreviewGenres.parse(row.genreRule);for(Entry e:source)if(PreviewGenres.matches(e.genres,genres))result.add(e);Comparator<Entry> order=row.sort.equals("title")?Comparator.comparing((Entry e)->PreviewPages.titleForSort(context,e),String.CASE_INSENSITIVE_ORDER):row.sort.equals("year")?Comparator.comparingInt(Entry::year).reversed():Comparator.comparingLong((Entry e)->e.added).reversed();result.sort(order.thenComparing(PreviewPages::displayName,String.CASE_INSENSITIVE_ORDER));if(row.maximum>0&&result.size()>row.maximum)return new ArrayList<>(result.subList(0,row.maximum));return result;}for(String key:row.members){for(Entry e:snapshot.movies)if(e.key().equals(key)){result.add(e);break;}for(Entry e:snapshot.shows)if(e.key().equals(key)){result.add(e);break;}}return result;}
 public void supersedeWatchNext(Set<String> continuing){boolean changed=false;for(Row row:rows)if(row.id.equals("watchnext"))changed|=row.members.removeAll(continuing);if(changed)save();}
 public boolean dismissed(Entry e){return prefs.contains("preview_cw_dismiss:"+e.key())&&e.playedAt<=prefs.getLong("preview_cw_dismiss:"+e.key(),0);}
 public void dismiss(Entry e){prefs.edit().putLong("preview_cw_dismiss:"+e.key(),e.playedAt).apply();}
 public static void add(Context c,Entry e,Runnable changed){if(e==null)return;PreviewHomeRows model=new PreviewHomeRows(c);List<Row> choices=new ArrayList<>();for(Row r:model.rows)if(r.custom()&&!r.dynamic||r.id.equals("watchnext"))choices.add(r);List<String> labels=new ArrayList<>();for(Row r:choices)labels.add((r.members.contains(e.key())?"Remove from ":"Add to ")+r.name);labels.add("Create new row…");PreviewDialog.choose(c,"Add to Row",labels.toArray(new String[0]),-1,n->{if(n==choices.size())model.name("Create new row","",name->{Row row=new Row("custom:"+UUID.randomUUID(),name);row.members.add(e.key());model.rows.add(row);model.save();changed.run();});else{Row row=choices.get(n);boolean removed=!row.members.add(e.key());if(removed)row.members.remove(e.key());model.save();PreviewNotice.show(c,(removed?"Removed from ":"Added to ")+row.name,false);changed.run();}});}
 private void name(String title,String previous,java.util.function.Consumer<String> accept){PreviewTextInput.show(context,title,previous,40,accept);}

 public static void clearWatchNext(Context c){PreviewDialog.choose(c,"Remove all titles from Watch Next?",new String[]{"Cancel","Clear"},0,n->{if(n==1){PreviewHomeRows model=new PreviewHomeRows(c);for(Row row:model.rows)if(row.id.equals("watchnext"))row.members.clear();model.save();PreviewNotice.show(c,"Watch Next cleared",false);}});}
 public static void customise(Context c,Runnable changed){new PreviewHomeRows(c).editor(changed);}
 private void editor(Runnable changed){Dialog dialog=new Dialog(context);LinearLayout screen=new LinearLayout(context);screen.setOrientation(LinearLayout.VERTICAL);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);screen.setPadding(dp(16),dp(12),dp(16),dp(12));screen.setBackground(PreviewDialog.surface(context,false));TextView heading=label("Customise Home",21);screen.addView(heading);TextView help=label("Select to edit · Up/Down to reorder",13);help.setPadding(0,dp(8),0,dp(16));screen.addView(help);ScrollView scroll=new ScrollView(context);LinearLayout list=new LinearLayout(context);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);screen.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));final String[] moving={null};final Runnable[] render={null};render[0]=()->{list.removeAllViews();for(Row row:rows){LinearLayout line=new LinearLayout(context);TextView move=control((row.id.equals(moving[0])?"↕  ":"")+row.name,()->{moving[0]=row.id.equals(moving[0])?null:row.id;save();render[0].run();View target=list.findViewWithTag(row.id);if(target!=null)target.requestFocus();});move.setTag(row.id);move.setOnKeyListener((v,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN||!row.id.equals(moving[0])||key!=KeyEvent.KEYCODE_DPAD_UP&&key!=KeyEvent.KEYCODE_DPAD_DOWN)return false;int index=rows.indexOf(row),next=index+(key==KeyEvent.KEYCODE_DPAD_UP?-1:1);if(next>=0&&next<rows.size()){Collections.swap(rows,index,next);save();render[0].run();list.findViewWithTag(row.id).requestFocus();}return true;});line.addView(move,new LinearLayout.LayoutParams(0,dp(36),1));TextView visible=control(row.visible?"Shown":"Hidden",()->{row.visible=!row.visible;save();render[0].run();list.findViewWithTag(row.id+":visibility").requestFocus();});visible.setTag(row.id+":visibility");line.addView(visible,new LinearLayout.LayoutParams(dp(95),dp(36)));if(row.custom()){TextView more=control("More",()->PreviewDialog.choose(context,row.name,new String[]{"Rename","Genre rule & contents","Delete row"},-1,n->{if(n==0)name("Rename row",row.name,value->{row.name=value;save();render[0].run();});else if(n==1)rule(row,()->{save();render[0].run();});else PreviewDialog.choose(context,"Delete row? Titles remain in your library",new String[]{"Cancel","Delete row"},0,answer->{if(answer==1){rows.remove(row);save();render[0].run();}});}));line.addView(more,new LinearLayout.LayoutParams(dp(82),dp(36)));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(3);list.addView(line,lp);}list.addView(control("Create new row…",()->name("Create new row","",name->{Row row=new Row("custom:"+UUID.randomUUID(),name);row.dynamic=true;rows.add(row);save();rule(row,()->{save();render[0].run();});render[0].run();})),new LinearLayout.LayoutParams(-1,dp(36)));};render[0].run();dialog.setContentView(screen);dialog.setOnDismissListener(d->changed.run());dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setDimAmount(.4f);dialog.getWindow().setLayout(Math.min(dp(430),context.getResources().getDisplayMetrics().widthPixels-dp(60)),Math.min(dp(Math.min(350,100+39*(rows.size()+1))),context.getResources().getDisplayMetrics().heightPixels-dp(100)));if(!rows.isEmpty())list.findViewWithTag(rows.get(0).id).requestFocus();}
 private void rule(Row row,Runnable changed){String[] labels={"Dynamic genre rule: "+(row.dynamic?"On":"Off"),"Genres: "+(row.genreRule.isEmpty()?"All":row.genreRule.replace("|",", ")),"Movies: "+(row.movies?"On":"Off"),"TV Shows: "+(row.tv?"On":"Off"),"Sort: "+row.sort,"Maximum items: "+(row.maximum==0?"No limit":row.maximum),"Done"};PreviewDialog.choose(context,row.name,labels,-1,n->{
  if(n==6){changed.run();return;}if(n==0)row.dynamic=!row.dynamic;
  if(n==1){Set<String> values=new TreeSet<>(Arrays.asList(PreviewGenres.NAMES));Snapshot snapshot=PreviewLibraryLoader.memoryCache();if(snapshot!=null){for(Entry e:snapshot.movies)values.addAll(PreviewGenres.parse(e.genres));for(Entry e:snapshot.shows)values.addAll(PreviewGenres.parse(e.genres));}PreviewGenres.choose(context,values,PreviewGenres.parse(row.genreRule),selected->{row.genreRule=android.text.TextUtils.join("|",selected);row.dynamic=true;save();rule(row,changed);});return;}
  if(n==2){if(row.movies&&!row.tv){PreviewNotice.show(context,"Keep Movies or TV Shows enabled",false);}else row.movies=!row.movies;}
  if(n==3){if(row.tv&&!row.movies){PreviewNotice.show(context,"Keep Movies or TV Shows enabled",false);}else row.tv=!row.tv;}
  if(n==4){PreviewDialog.choose(context,"Row sort",new String[]{"Date Added","Title","Year"},Arrays.asList("added","title","year").indexOf(row.sort),i->{row.sort=new String[]{"added","title","year"}[i];save();rule(row,changed);});return;}
  if(n==5){PreviewTextInput.show(context,"Maximum items · 0 means no limit",String.valueOf(row.maximum),5,value->{try{row.maximum=Math.max(0,Integer.parseInt(value));save();}catch(NumberFormatException error){PreviewNotice.show(context,"Enter a whole number",false);}rule(row,changed);});return;}
  save();rule(row,changed);
 });}
 private TextView label(String text,int size){TextView v=new TextView(context);v.setText(text);v.setTextSize(size);v.setTextColor(0xffd6e5ef);return v;}
 private TextView control(String text,Runnable action){TextView v=label(text,14);v.setGravity(Gravity.CENTER_VERTICAL);v.setPadding(dp(12),0,dp(12),0);v.setFocusable(true);v.setFocusableInTouchMode(true);v.setBackground(PreviewDialog.focus(context));v.setOnClickListener(w->action.run());return v;}
 private int dp(int n){return PreviewDialog.dp(context,n);}
}
